// 1. 创建日期时间
LocalDate today = LocalDate.now();                    // 2026-05-29
LocalDate birthday = LocalDate.of(1995, 6, 15);      // 1995-06-15
LocalTime now = LocalTime.now();                      // 14:30:25.123
LocalDateTime dateTime = LocalDateTime.of(2026, 5, 29, 14, 30);

// 2. 日期时间运算
LocalDate nextWeek = today.plusWeeks(1);
LocalDate lastMonth = today.minusMonths(1);
Duration duration = Duration.ofHours(2).plusMinutes(30); // 2小时30分
Period period = Period.between(birthday, today);      // 计算年龄间隔

// 3. 格式化与解析
DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
String formatted = dateTime.format(fmt);             // "2026-05-29 14:30:00"
LocalDateTime parsed = LocalDateTime.parse("2026-05-29 14:30:00", fmt);

// 4. 时区处理
ZonedDateTime shanghai = ZonedDateTime.now(ZoneId.of("Asia/Shanghai"));
ZonedDateTime tokyo = shanghai.withZoneSameInstant(ZoneId.of("Asia/Tokyo"));

// 5. 时间戳转换
Instant timestamp = Instant.now();
Date legacyDate = Date.from(timestamp);
Instant backToInstant = legacyDate.toInstant();
